def new_fields(harvests, seen=set()):
    """Return each field the first time it appears among the harvests, in order. field values already in `seen` are left out."""
    harvests = list(harvests)
    out = []
    for x in harvests:
        if x.field not in seen:
            seen.add(x.field)
            out.append(x.field)
    return out
